/* Real host + real Space panel. Owns windows; never injects physical input. */
#define COBJMACROS
#define wWinMain git_unused_host_entrypoint
#include "../app/fpdemo.c"
#undef wWinMain
static int passed,failed;static wchar_t left[32768],right[32768];
#define CHECK(label,condition) do{if(condition){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static void pump_space(int ms){uint64_t end=GetTickCount64()+ms;do{MSG m;while(PeekMessageW(&m,NULL,0,0,PM_REMOVE))if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(2);}while(GetTickCount64()<end);}
static const wchar_t *space_test_name(Pane *p){return p->view&&p->cursor<p_count(p)?fpe_view_name(p->view,p->cursor):NULL;}
static int wait_space(void){uint64_t end=GetTickCount64()+15000;while(g_space_state==SP_RUNNING&&GetTickCount64()<end)pump_space(5);return g_space_state==SP_COMPLETE;}


static int wait_git(void){uint64_t end=GetTickCount64()+30000;while((g_git_state.state==GIT_LOADING||!g_git_state.generation)&&GetTickCount64()<end)pump_space(5);return g_git_state.state==GIT_READY;}
static void request_git(uint64_t session,uint32_t generation,uint32_t action,uint32_t staged,const wchar_t *relative){git_action a={session,generation,action,staged,0};size_t n=(wcslen(relative)+1)*2;uint8_t *p=malloc(sizeof a+n);memcpy(p,&a,sizeof a);memcpy(p+sizeof a,relative,n);panel_message(git_app(),PANELP_GIT_ACTION,p,(uint32_t)(sizeof a+n));free(p);}
static void test_git_host_explicit_status_badges_and_reuse(void){CHECK("Git remains dormant while browsing",!sidepanel_running(git_app())&&!g_git_model.root);fn_ctx c;app_pane_ctx(&c,&g.panes[0],FN_FROM_CODE);c.n=c.dirs=0;c.state=FN_S_FOLDER;c.dir=left;CHECK("Git status registered and available",fn_find("git.status")&&fn_applies(fn_find("git.status"),&c));fn_run(fn_find("git.status"),&c);app_ctx_free(&c);CHECK("actual helper populates host snapshot",wait_git()&&git_find(&g_git_model,L"both.md"));wchar_t mark[4];CHECK("optional host badges use actual snapshot",g_git_badges&&git_badge(&g_git_model,left,L"both.md",0,mark)&&!wcscmp(mark,L"MM"));uint64_t session=g_git_request.session;uint32_t generation=sidepanel_generation(git_app());p_navigate(&g.panes[0],right,NULL,1);pump_space(80);CHECK("browsing does not trigger Git refresh",g_git_request.session==session);sidepanel_close();pump_space(30);CHECK("hiding retains owned Git helper",sidepanel_running(git_app()));pane_run(active_pane(),"git.show",FN_FROM_CODE);pump_space(40);CHECK("show reuses snapshot and process",sidepanel_open()&&g_git_request.session==session&&sidepanel_generation(git_app())==generation);}
static void test_git_host_scope_preview_and_actual_diff(void){uint64_t session=g_git_request.session,before=g.panes[1].nav_ticket;uint32_t generation=g_git_state.generation;request_git(session+1,generation,GIT_RIGHT,0,L"both.md");request_git(session,generation+1,GIT_RIGHT,0,L"both.md");request_git(session,generation,GIT_RIGHT,0,L"..\\outside");request_git(session,generation,GIT_RIGHT,0,L"not-in-snapshot");CHECK("stale and unlisted result actions rejected",g.panes[1].nav_ticket==before);request_git(session,generation,GIT_RIGHT,0,L"both.md");uint64_t end=GetTickCount64()+7000;while((!g.panes[1].path||wcscmp(g.panes[1].path,left)||!space_test_name(&g.panes[1])||wcscmp(space_test_name(&g.panes[1]),L"both.md"))&&GetTickCount64()<end)pump_space(5);CHECK("Git result reveals actual file in right pane",g.panes[1].path&&!wcscmp(g.panes[1].path,left)&&space_test_name(&g.panes[1])&&!wcscmp(space_test_name(&g.panes[1]),L"both.md"));request_git(session,generation,GIT_PREVIEW,0,L"both.md");end=GetTickCount64()+7000;while(g.pv_shown!=3&&GetTickCount64()<end)pump_space(5);CHECK("Git preview uses existing text handler",g.pv_shown==3&&IsWindowVisible(textview_window()));request_git(session,generation,GIT_DIFF,1,L"both.md");end=GetTickCount64()+15000;while(g_diff_state.state==DIFF_LOADING&&GetTickCount64()<end)pump_space(5);CHECK("real diff helper renders staged Git changes",g_diff_state.state==DIFF_READY&&g_diff_state.hunks==1&&g_diff_request.reserved==2&&g_diff_git.staged);pane_run(active_pane(),"git.show",FN_FROM_CODE);pump_space(50);request_git(session,generation,GIT_DIFF,0,L"both.md");end=GetTickCount64()+15000;while(g_diff_state.state==DIFF_LOADING&&GetTickCount64()<end)pump_space(5);CHECK("same helper switches to index-versus-working diff",g_diff_state.state==DIFF_READY&&g_diff_request.reserved==1&&g_diff_state.hunks==1);pane_run(active_pane(),"git.show",FN_FROM_CODE);pump_space(50);request_git(session,generation,GIT_TERMINAL,0,L"");pump_space(500);CHECK("repository terminal launches existing helper",sidepanel_running(term_app())&&sidepanel_app()&&!_wcsicmp(sidepanel_app(),term_app()));}
static void test_git_host_disable_and_registry(void){const char *badges="[functions]\nsvc.shell = off\nsvc.icons = off\n[git.status]\nbadges = off\n[panel.side]\nslide = off\n";fn_settings(badges,strlen(badges));fn_configure_all();CHECK("badge option disables painting without a rescan",!g_git_badges&&g_git_model.root);wchar_t native[32768];DWORD supplied=GetEnvironmentVariableW(L"OPENPILOT_GIT_WORKTREE",native,32768);CHECK("native host fixture supplied",supplied&&supplied<32768);if(supplied&&supplied<32768){git_open_folder(native);CHECK("real host accepts native worktree snapshot",wait_git()&&g_git_model.native&&g_git_model.root);const char *off="[functions]\nwsl.helper = off\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(off,strlen(off));fn_configure_all();pump_space(50);CHECK("disabling WSL retires native Git helper and cache",!sidepanel_running(git_app())&&!g_git_model.root&&g_git_state.state==GIT_STOPPED);}const char *settings="[functions]\ngit.status = off\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();pump_space(40);CHECK("disabled Git retires its cache and helper",!fn_active(fn_find("git.status"))&&!g_git_model.root&&!sidepanel_running(git_app())&&!g_git_badges);char report[65536];fn_report_csv(report,sizeof report);CHECK("registry lifecycle remains valid",strstr(report,"metric,fn_violations,,,,0,")!=NULL);CHECK("commands fit registry",fn_find("git.result")&&fn_find("duplicates.copy_path")&&fn_find("wsl.helper"));}
int wmain(int argc,wchar_t **argv){if(argc!=3)return 2;wcsncpy(left,argv[1],32767);wcsncpy(right,argv[2],32767);CoInitializeEx(NULL,COINIT_APARTMENTTHREADED);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);fn_host host={host_now,host_arm,host_status};fn_init(&host);fn_register(app_functions,sizeof app_functions/sizeof *app_functions);functions_register();relay_register();palette_register();const char *settings="[functions]\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();g.engine=fpe_engine_create(NULL);g.dual=1;g.ratio=0.5;session_defaults(&g_ses);for(int i=0;i<2;i++){Pane *p=&g.panes[i];p->idx=i;p->ntabs=1;p->drop_row=-1;p->opts.dirs_first=1;}HINSTANCE instance=GetModuleHandleW(NULL);register_class(L"OpenPilot",main_proc,0,instance);register_class(L"OpenPilotPane",pane_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotTree",tree_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotDebug",dbg_proc,0,instance);HWND window=CreateWindowExW(0,L"OpenPilot",L"Owned Git integration",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,80,80,1300,820,NULL,NULL,instance,NULL);if(!window)return 3;for(int i=0;i<2;i++){fpe_dir *dir=read_start(i?right:left);if(dir){p_show_dir(&g.panes[i],dir,NULL,0);fpe_dir_release(dir);}}ShowWindow(window,SW_SHOWNOACTIVATE);UpdateWindow(window);pump_space(20);test_git_host_explicit_status_badges_and_reuse();test_git_host_scope_preview_and_actual_diff();test_git_host_disable_and_registry();DestroyWindow(window);pump_space(100);settings_save_join();folderwatch_join();fpe_engine_destroy(g.engine);free(g_space_root);CoUninitialize();printf("%d passed, %d failed; 3 Git host selectors\n",passed,failed);return failed?1:0;}
